<?php
if (!preg_match('#^/pagar/([A-Za-z0-9_-]+)$#',$path,$m)) { http_response_code(404); exit('Not found'); }
$q=db()->prepare('SELECT * FROM payment_links WHERE token_hash=?');$q->execute([token_hash($m[1])]);$link=$q->fetch();if(!$link||$link['status']!=='ACTIVE'){http_response_code(404);exit('Link invalido.');}$error=null;$result=null;$pm=$_POST['payment_method']??'PIX';
if($method==='POST'){try{$fs=['name','email','cpf_cnpj','phone','postal_code','address','address_number','province','city','state'];$d=[];foreach($fs as $f){$d[$f]=trim((string)($_POST[$f]??''));if($d[$f]==='')throw new RuntimeException('Campos obrigatorios ausentes');}$cpf=preg_replace('/\D+/','',$d['cpf_cnpj']);$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare('SELECT * FROM customers WHERE cpf_cnpj=? LIMIT 1');$s->execute([$cpf]);$old=$s->fetch();if($old){$cid=(int)$old['id'];$gid=$old['asaas_customer_id'];}else{$pdo->prepare('INSERT INTO customers(name,email,cpf_cnpj,phone,postal_code,address,address_number,province,city,state) VALUES(?,?,?,?,?,?,?,?,?,?)')->execute([$d['name'],$d['email'],$cpf,preg_replace('/\D+/','',$d['phone']),preg_replace('/\D+/','',$d['postal_code']),$d['address'],$d['address_number'],$d['province'],$d['city'],strtoupper($d['state'])]);$cid=(int)$pdo->lastInsertId();$gid=null;}$g=new AsaasGateway();if(!$gid){$d['cpf_cnpj']=$cpf;$d['external_reference']='customer:'.$cid;$gid=$g->createCustomer($d);$pdo->prepare('UPDATE customers SET asaas_customer_id=? WHERE id=?')->execute([$gid,$cid]);}$a=['gateway_customer_id'=>$gid,'amount_cents'=>(int)$link['amount_cents'],'description'=>$link['description'],'external_reference'=>'link:'.$link['id'],'due_date'=>date('Y-m-d'),'billing_type'=>$pm];if($pm==='CREDIT_CARD'){$a['creditCard']=['holderName'=>$_POST['card_holder'],'number'=>preg_replace('/\D+/','',$_POST['card_number']),'expiryMonth'=>$_POST['card_month'],'expiryYear'=>$_POST['card_year'],'ccv'=>$_POST['card_cvv']];$a['creditCardHolderInfo']=['name'=>$d['name'],'email'=>$d['email'],'cpfCnpj'=>$cpf,'postalCode'=>preg_replace('/\D+/','',$d['postal_code']),'addressNumber'=>$d['address_number'],'phone'=>preg_replace('/\D+/','',$d['phone']),'mobilePhone'=>preg_replace('/\D+/','',$d['phone'])];$result=$g->createTransparentPayment($a);}else{$result=$g->createPayment($a);if($pm==='PIX')$result['pix']=$g->pix($result['id']);if($pm==='BOLETO')$result['boleto']=$g->boleto($result['id']);}$pdo->commit();}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log('[checkout] '.$e->getMessage());$error='Nao foi possivel processar o pagamento. Tente novamente.';}}
?><!doctype html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pagamento | Checkout 360BH</title><link rel="stylesheet" href="/assets/checkout.css?v=20260924"></head><body><main class="checkout"><div class="brand">360BH<small>Checkout seguro de pagamento</small></div><section class="card"><h1><?=htmlspecialchars($link['description'])?></h1><div class="value">R$ <?=money((int)$link['amount_cents'])?></div><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><?php if($result&&$pm==='PIX'):?><h2>Pix gerado</h2><img style="max-width:240px" src="data:image/png;base64,<?=htmlspecialchars($result['pix']['encodedImage']??'')?>"><textarea readonly><?=htmlspecialchars($result['pix']['payload']??'')?></textarea><?php elseif($result&&$pm==='BOLETO'):?><h2>Boleto gerado</h2><textarea readonly><?=htmlspecialchars($result['boleto']['identificationField']??'')?></textarea><?php elseif($result):?><div class="success">Pagamento enviado para autorizacao.</div><?php else:?><div id="lookup" class="note"></div><form method="post" id="checkout-form"><div class="grid"><div class="field full"><label>CPF/CNPJ *</label><input id="cpf_cnpj" name="cpf_cnpj" required></div><div class="field"><label>Nome completo *</label><input id="name" name="name" required></div><div class="field"><label>E-mail *</label><input id="email" name="email" type="email" required></div><div class="field"><label>Celular *</label><input id="phone" name="phone" required></div><div class="field"><label>CEP *</label><input id="postal_code" name="postal_code" required></div><div class="field"><label>Logradouro *</label><input id="address" name="address" required></div><div class="field"><label>N&uacute;mero *</label><input id="address_number" name="address_number" required></div><div class="field"><label>Bairro *</label><input id="province" name="province" required></div><div class="field"><label>Cidade *</label><input id="city" name="city" required></div><div class="field"><label>Estado *</label><input id="state" name="state" maxlength="2" required></div><div class="field full"><label>Forma de pagamento</label><select name="payment_method" id="payment_method"><option value="PIX">Pix</option><option value="BOLETO">Boleto</option><option value="CREDIT_CARD">Cartao de credito</option></select></div><div id="card-fields" class="field full" hidden><input name="card_holder" placeholder="Nome no cartao"><input name="card_number" placeholder="Numero do cartao"><input name="card_month" placeholder="Mes"><input name="card_year" placeholder="Ano"><input name="card_cvv" placeholder="CVV"></div></div><button class="btn">Continuar para pagamento</button></form><?php endif;?></section></main><script src="/assets/checkout.js?v=20260924"></script><script>let p=document.getElementById('payment_method'),c=document.getElementById('card-fields');if(p)p.onchange=()=>c.hidden=p.value!=='CREDIT_CARD';</script></body></html><?php exit;
